-- UniBite · katalogu i plotë: qytetet, fotot dhe menuja
-- Ekzekutohet në Supabase → SQL Editor. I përsëritshëm (mund të bëhet Run përsëri).

-- 1) qyteti për filtrin e lokacionit
alter table public.restaurants add column if not exists city text;
update public.restaurants set city = 'Mitrovicë' where city is null;

